%[text] ## Plot Shad redox probes with water table or predicted tide peaks and battery. 
%[text] L07, L08, L09 are next to the channel bank. L10, L11, L12 are in about 4 meters in short *Spartina alterniflora*.
%[text] Note: Ref\_05, used as the base reference, became unstable and Ref\_06 was which in as base on 2026-05-13 11:00:00.
%[text] Ref\_06 as base became unstable 2026-08-10 19:24:00.
%[text] ![](text:image:1441)
% Load files if not processed in in current session of matlab
% The redox files, ""..._Eh" have temperature corrected Eh.
load("TidesTimetable.mat")
load("TidesPeaks.mat")
% If well data available then load the following
    % load("lowMarshWaterTable.mat")
    % load("lowMarshWTPeaks.mat")
load("lowMarshMinuteTbl.mat")
load("lowMarshMinuteTbl_Eh.mat")
load("lowMarsh5MinuteTbl.mat")
load("lowMarsh5MinuteTbl_Eh.mat")

% NaN out redox values affected by low battery / logger shutdowns.
%     lowMarsh5MinuteTbl = maskPowerLoss(lowMarsh5MinuteTbl, lowMarsh5MinuteTbl);
%     lowMarshMinuteTbl  = maskPowerLoss(lowMarshMinuteTbl,  lowMarsh5MinuteTbl);


% Plot the water table or predicted tide and battery on right axis and each probe depths on left.
% Recreate the water table graph for each figure
startDate = datetime("2026-05-20 08:00:00","TimeZone","-05:00");
[endDate, idx] = max(lowMarshMinuteTbl.TIMESTAMP);
probes = (["L12","L11","L10","L09","L08","L07"]);
allVars = lowMarshMinuteTbl.Properties.VariableNames;
figName = strcat("Low Marsh probe ",probes);
customColors = [0 1 1;0 1 0;1 0 0;0 0 0;0.1843,0.7451,0.9373;0.2902,0.9412,0.1882;0.9608,0.4118,0.4118;0.6196,0.5843,0.5843;0 0.4 0]; % cyan,green,red,black
%customColors = orderedcolors("gem12");
customLineStyles = ["-";":";"-.";"-";"-";":";"-.";"-"];
% widths = [1.5,2.0,2.5,2.75,1.5,2.0,2.5,2.75]; % Vary the line widths
widths = [1.0,1.0,1.0,1.0,1.5,2.0,2.5,2.75]; % Vary the line widths
% plot probes. Include late season adjustment.
% Only plot the adjusted values where a correction was applied
% (adjusted value differs from the raw value).
lowMarshMinuteTbl_p = maskPowerLoss(lowMarshMinuteTbl,  lowMarsh5MinuteTbl);
 for f = 1:numel(probes)      %[output:group:53882438]
    fig = figure(); %[output:950b7a10] %[output:293568be] %[output:98295d21] %[output:2cbe7ad0] %[output:9ff97bc4] %[output:060be37c]
    fig.NumberTitle = "off"; %[output:950b7a10] %[output:293568be] %[output:98295d21] %[output:2cbe7ad0] %[output:9ff97bc4] %[output:060be37c]
    rawVars = string(allVars(contains(allVars, probes(f)) & endsWith(allVars, "cm")));
    adjVars = rawVars + "Adjusted";
    for k = 1:numel(adjVars)
        notAdjusted = lowMarshMinuteTbl_p.(adjVars(k)) == lowMarshMinuteTbl_p.(rawVars(k));
        lowMarshMinuteTbl_p.(adjVars(k))(notAdjusted) = NaN;
    end
    vars = [rawVars, adjVars];
    fig.Name = figName(f);
    title(strcat("Low Marsh Probe",probes(f)," with predicted tide height"));   
    hold on;
    yyaxis('left');
    % Set up line type and widths
    ax = gca;
    ax.YColor = [0 0 0]; 
    ax.ColorOrder = customColors;
    ax.LineStyleOrder = customLineStyles;
    ax.LineStyleCyclingMethod ="withcolor";   

    % Plot a probe's depths on a plot
    hProbe= plot(lowMarshMinuteTbl_p, "TIMESTAMP", vars);
    % Vary the line widths       
    for k = 1:numel(hProbe) 
        hProbe(k).LineWidth = widths(k);        
    end
    % Set up the legend
    for k = 1:numel(hProbe)
        hProbe(k).DisplayName = string(extractBetween(vars(k), "_", "Adjusted"));
        legend('Orientation','horizontal','Location','bestoutside','NumColumns',3);
    end

    ylim([-425 60]);
    ylabel('(mV)');
    xlabel('Date Time');
   
    % == Plot water table on right axis ==== 
    yyaxis(ax,'right');
    ax.YColor = [0 0 0]; 
    % ax.XColor = [0 0 0];
    midgrey = [0.5 0.5 0.5] ;
    % plot(lowMarshMinuteTbl,"TIMESTAMP","LoggerBattV_MIN",Color=midgrey, DisplayName="LoggerBatteryV")
    ylabel('meter(Predicted Tide)',Color="k");
    ylim([8 18]);
    xlim(ax,[startDate max(lowMarshMinuteTbl.TIMESTAMP)]);
    % xlim([datetime(2026,9,29,11,54,54,"TimeZone","-05:00")...
    %     max(lowMarshMinuteTbl.TIMESTAMP)])
    hold on
    fig_water = plot(TidesTimetable.DateTime,TidesTimetable.Prediction,'DisplayName',"Predicted Tide",Color = midgrey,LineStyle="-");
    
    % Plot vertical lines at water table peaks   
    % h = xline(Tidepeaks.DateTime, ':b', 'LineWidth', .5);
    % % Give only the first xline a name; hide the rest from legend
    % h(1).DisplayName = 'Predicted Tide High Peaks';
    % for k = 2:numel(h)
    %     h(k).HandleVisibility = 'off';       
    % end
    % lines = findall(ax, 'Type', 'line');  % returns handles
    legend({'5cm','10cm','15cm','30cm','5cm_adj','10cm_adj','15cm_adj','30cm_adj',"Predicted Tide"},'Location','southoutside'); 
    ax.Toolbar.Visible = 'on';

    % savefig(gcf,strcat("results\LowMarshProbe_adjusted",probes(f),".fig"));
    hold off;
 end %[output:group:53882438]
%%
%[text] Plot references
 fig = figure(); %[output:9351cef5]
 vars = allVars(contains(allVars, "Ref"));  
 fig_ref = plot(lowMarshMinuteTbl_Eh, "TIMESTAMP",vars); %[output:9351cef5]
 hold on %[output:9351cef5]
 for k = 1:numel(fig_ref)
     fig_ref(k).DisplayName = string(vars(k)); %[output:9351cef5]
 end
 title("Reference probes"); %[output:9351cef5]
 ylabel('Eh(mV)'); %[output:9351cef5]
 ax = gca;
 ax.YColor = [0 0 0];  %[output:9351cef5]
 ax.ColorOrder = customColors; %[output:9351cef5]
 ax.LineStyleOrder = customLineStyles; %[output:9351cef5]
 ax.LineStyleCyclingMethod = "withcolor";  %[output:9351cef5]
 xlim(ax,[startDate max(lowMarshMinuteTbl_Eh.TIMESTAMP)]);     %[output:9351cef5]
 legend('Interpreter', 'none'); % Don't interpret "_" as subscripts %[output:9351cef5]
 hold off    %[output:9351cef5]
%%
%[text] ## Plot battery voltage and temperature probes.
% plot battery volts
figure; %[output:7bb25e91]
all5Vars = lowMarsh5MinuteTbl.Properties.VariableNames;
batVars = all5Vars(contains(all5Vars, 'batt', IgnoreCase=true));

fig_ref = plot(lowMarsh5MinuteTbl, "TIMESTAMP",batVars); %[output:7bb25e91]
hold on %[output:7bb25e91]
title("Battery volts"); %[output:7bb25e91]
ylabel('volts'); %[output:7bb25e91]
xlim(ax,[startDate max(lowMarsh5MinuteTbl.TIMESTAMP)]);     %[output:953bd364]
legend('Interpreter', 'none'); % Don't interpret "_" as subscripts %[output:7bb25e91]
hold off  %[output:7bb25e91]

% Plot soil Temperatures Celsius

figure;  %[output:8108daa7]
allVars_5Minute = lowMarsh5MinuteTbl.Properties.VariableNames;
vars = allVars_5Minute(contains(allVars_5Minute, "Soil_C"));  
fig_soil = plot(lowMarsh5MinuteTbl, "TIMESTAMP",vars); %[output:8108daa7]
title("Low Marsh Soil Temperature"); %[output:8108daa7]
ylabel('Celsius'); %[output:8108daa7]
legend %[output:8108daa7]

